"""Shared teaching additions; no patient analysis or clinical-model fitting."""

def guide_additions(lang):
    tr = lang == 'tr'
    def t(a,b): return a if tr else b
    blocks=[]
    def chapter(n,a,b): blocks.append(dict(type='chapter',number=n,text=t(a,b)))
    def p(a,b): blocks.append(dict(type='paragraph',text=t(a,b)))
    def heading(a,b): blocks.append(dict(type='heading',text=t(a,b)))
    def note(a,b): blocks.append(dict(type='note',text=t(a,b)))
    def equation(text,steps=None):
        block=dict(type='math',text=text)
        if steps:block['mobile_steps']=steps
        blocks.append(block)
    def table(a,b,rows):blocks.append(dict(type='table',headers=t(a,b),rows=rows))
    def link(text,url):blocks.append(dict(type='link',text=text,url=url))

    chapter(16,'Yapay zekâ diyoruz; bizim modelimiz bunun neresinde?','Where does our calculator fit within AI?')
    p('Yapay zekâ (AI, Artificial Intelligence), bilgisayarlara öğrenme ve problem çözme gibi görevler yaptıran geniş alandır. Makine öğrenmesi (ML, Machine Learning), kuralları yalnız elle yazmak yerine veriden örüntü öğrenen yöntemleri kapsar. Derin öğrenme (DL, Deep Learning) ise çok katmanlı yapay sinir ağlarını kullanan makine öğrenmesi yöntemleridir.',
      'Artificial intelligence (AI) is the broad field of making computers perform tasks such as learning and problem solving. Machine learning (ML) includes methods that learn patterns from data rather than relying only on hand-written rules. Deep learning (DL) uses artificial neural networks with many layers and is one part of machine learning.')
    note('Yapay zekâ → makine öğrenmesi → denetimli öğrenme → bizim lojistik regresyon modelimiz. Derin öğrenme, makine öğrenmesinin başka bir yöntem grubudur; hesaplayıcımız derin sinir ağı kullanmaz.',
         'AI → machine learning → supervised learning → our logistic regression model. Deep learning is another family of machine-learning methods; our calculator does not use a deep neural network.')
    p('Denetimli öğrenmede eğitim örneklerinin kayıtlı sonuç etiketleri vardır. Bizim çalışmamızda girdiler tanı yaşı, aile öyküsü ve belirli tümör özellikleri; öğrenilmek istenen etiket ise kayıtlı BRCA sonucudur. Eğitimde sonucu biliriz. Yeni bir kişiye tahmin yaparken ise sonuç-öncesi bilgileri kullanmak gerekir. Sonucu öğrendikten sonra kaydedilen bilgileri sanki önceden biliniyormuş gibi kullanmak, gerçek kullanımın güvenilir bir denemesi olmaz.',
      'In supervised learning, training examples have recorded outcome labels. Our inputs include diagnosis age, family history and selected tumour features; the target is the recorded BRCA result. We know the outcome during training. For a new prediction, the inputs must be available before the result. Treating information recorded afterwards as if it had been known earlier does not faithfully test intended use.')
    heading('Aynı alanda farklı sorular','Different questions in the same field')
    table(['Soru','Girdi → çıktı','Bizim hesaplayıcı mı?'],['Question','Input → output','Our calculator?'],[
        (t('BRCA sonucu olasılığı','BRCA-result probability'),t('Klinik bilgiler → kayıtlı pozitif sonuç olasılığı','Clinical features → probability of a recorded positive result'),t('Evet; araştırma modeli','Yes; a research model')),
        (t('Varyant çağırma','Variant calling'),t('Dizileme okumaları → DNA değişikliği çağrısı','Sequencing reads → DNA variant call'),t('Hayır; ör. DeepVariant ayrı görevdir','No; DeepVariant is an example of a separate task')),
        (t('Varyantın anlamı','Variant interpretation'),t('Bir değişiklik ve kanıtları → klinik sınıflama','A variant and supporting evidence → clinical classification'),t('Hayır; VUS bu modelle yeniden sınıflanmaz','No; this model does not reclassify a VUS')),
        (t('Gelecekte kanser / tedavi yanıtı','Future cancer / treatment response'),t('Uygun başlangıç bilgileri ve takip → gelecekteki sonuç','Suitable baseline data and follow-up → a future outcome'),t('Hayır; farklı hedef ve doğrulama gerekir','No; a different target and validation are required')),
    ])
    p('Karmaşıklık, doğruluğun garantisi değildir. Lojistik regresyon her girdiye bir katsayı verir; karar ağacı sorularla dallanır; K-en yakın komşu (KNN, K-Nearest Neighbours) benzer eğitim örneklerine bakar; destek vektör makinesi (SVM, Support Vector Machine) sınıfları ayıran bir sınır öğrenir; sinir ağları katmanlar boyunca dönüşümler öğrenir. Bu açıklamalar bir algoritma yarışmasının sonucu değildir. Bizim verimizde hangisinin daha iyi olduğunu söylemek, aynı hastalar ve aileleri ayıran aynı değerlendirme düzeniyle adil bir karşılaştırma gerektirir; burada böyle bir yeni karşılaştırma yapılmadı.',
      'Complexity does not guarantee accuracy. Logistic regression assigns a coefficient to each input; a decision tree branches through questions; K-nearest neighbours (KNN) looks at similar training examples; a support vector machine (SVM) learns a separating boundary; neural networks learn transformations through layers. These descriptions are not the results of an algorithm competition. Establishing which works better for our data would require a fair comparison using the same patients and family-separated evaluation. No new comparison was performed here.')
    link(t('DeepVariant: özgün varyant çağırma çalışması','DeepVariant: original variant-calling study'),'https://www.nature.com/articles/nbt.4235')

    chapter(17,'Bilgisayar hatalarından nasıl öğreniyor?','How does the computer learn the coefficients?')
    note('Aşağıdaki sayılar yalnız kurgu bir ders örneğidir. Gerçek hasta, gerçek eğitim adımı veya yeni performans sonucu değildir. Hesaplayıcının kayıtlı katsayıları değiştirilmedi.',
         'The numbers below are a fictional classroom example only. They are not a real patient, an actual training iteration or a new performance estimate. The calculator’s stored coefficients were not changed.')
    p('Öğrenme döngüsü: katsayılarla tahmin üret → kayıtlı etiketle karşılaştır → kaybı hesapla → katsayıları birlikte güncelle → tekrar et. En sonda yalnız eğitim hatası değil, eğitim dışında tutulan örneklerdeki sonuç da önemlidir. 5. bölüm, geçmiş çalışmada bu işin hangi ayarlar ve sınırlılıklarla yapıldığını anlatır.',
      'The learning cycle is: predict using coefficients → compare with the recorded label → calculate loss → update coefficients together → repeat. Performance on examples held outside fitting matters as well as training error. Chapter 5 describes the settings and limitations of how the historical work did this.')
    p('Kayıp (loss), bir tahminin kayıtlı etiketten ne kadar uzak olduğunu ölçen eğitim ölçütüdür. Logaritmik kayıp (log loss), yanlış bir sonuca aşırı güvenmeyi ağır cezalandırır. Aşağıda y kayıtlı etikettir: pozitif için 1, diğer etiket için 0. p, eğitim sırasında üretilen ham pozitif olasılığıdır; ekrandaki son kalibre yüzde değildir. ℓ (küçük L), bir örneğin kaybı; ln doğal logaritmadır.',
      'Loss measures how far a prediction is from its recorded label during training. Logarithmic loss (log loss) strongly penalises confident wrong predictions. Here y is the recorded label: 1 for Positive, 0 for other labels. p is the raw positive probability during training, not the final calibrated percentage on screen. ℓ (lower-case L) is one example’s loss; ln is the natural logarithm.')
    equation(r'\ell=-\left[y\ln(p)+(1-y)\ln(1-p)\right]',[
        r'y=1:\quad\ell=-\ln(p)',r'y=0:\quad\ell=-\ln(1-p)'])
    heading('Tek bir pozitif etiketli kurgu örnek','One fictional example labelled positive')
    p('Kayıtlı etiketi pozitif olan bir örneğe %20 ham olasılık verilirse kayıp yaklaşık 1,609 olur. Aynı örneğe %80 verilirse yaklaşık 0,223 olur. Pozitif örneğe yalnız %1 vermek ise yaklaşık 4,605 kayıp üretir: bu, güvenle yapılmış yanlış tahminin daha ağır cezasıdır.',
      'For an example labelled positive, predicting a raw probability of 20% gives a loss of about 1.609. Predicting 80% for that same example gives about 0.223. Assigning only 1% to a positive example gives about 4.605: a larger penalty for a confident wrong prediction.')
    equation(r'-\ln(0.20)\approx1.609')
    equation(r'-\ln(0.80)\approx0.223')
    equation(r'-\ln(0.01)\approx4.605')
    p('Eğitim, tek bir örneğin yüzdesini artırma işi değildir: başka örneklerdeki hatalar da hesaba katılır. Sınıf ağırlıkları, az sayıdaki pozitif kayıtlardaki hatalara daha fazla ağırlık verir. L2 cezası, aşırı büyük katsayılara karşı denge kurar. Kaybın azalması eğitim verisine daha iyi uyum anlamına gelebilir; yeni hastalarda daha iyi sonuç alınacağını tek başına göstermez.',
      'Training does not simply increase one example’s percentage: errors on other examples also matter. Class weights give more influence to errors on the smaller positive class. The L2 penalty counterbalances excessively large coefficients. Lower loss can mean a better fit to the training data; it does not by itself establish better performance in new patients.')
    p('Bir katsayı β olsun. Kare cezasında β=1 için katkı 1, β=3 için katkı 9’dur; toplam cezanın büyüklüğü ayrıca ceza ayarına bağlıdır. Bu yalnız cezanın biçimini anlatır. Bizim kayıtlı ayarımızda C küçüldükçe düzenlileştirme güçlenir. C, elle hastaya göre ayarlanan bir risk düğmesi değildir.',
      'For a coefficient β, the squared-penalty contribution is 1 when β=1 and 9 when β=3; total penalty strength also depends on its setting. This illustrates only the shape of the penalty. Under our stored parameterisation, smaller C means stronger regularisation. C is not a patient-specific risk control to adjust manually.')
    equation(r'1^2=1,\qquad3^2=9')
    heading('Eğitim ile kullanım farklı işlerdir','Training and use are different activities')
    p('Eğitimde etiketlerden katsayılar öğrenilir; daha sonra kalibrasyon ve karar kuralları değerlendirilir. Canlı kullanımda kayıtlı katsayılar sabittir: girdiyi değiştirdiğinizde yalnız mevcut formüller yeniden hesaplanır. Girdileriniz yeni eğitim örneği olarak kaydedilmez. Bir öğrencinin kurgu profilindeki yüzdeyi değiştirmesi, modelin başarısını veya biyolojik bir etkiyi ölçmez.',
      'During training, labels help determine coefficients; calibration and decision rules are then evaluated. During live use, the stored coefficients are fixed: editing an input only recomputes the existing formulas. Your entries are not stored as new training examples. Changing a fictional profile’s percentage does not measure model performance or a biological effect.')
    p('Web sayfasındaki sekiz kurgu örnekle öğrenmeyi adım adım izleyebilirsiniz. Geri dönüp katsayıları, hataları ve yeni tahminleri karşılaştırın. Bu küçük ders deneyi gerçek modelin eğitim kaydı değildir.',
      'The web lesson lets you follow learning step by step with eight fictional examples. Go back to compare weights, errors and new predictions. This small classroom experiment is not a record of the actual model’s training.')
    link(t('Kurgu verilerle öğrenmeyi izleyin','Watch learning with fictional data'),'https://brca-istun.streamlit.app/?sayfa=model&dil='+lang+'&ogren=1')
    link(t('Log loss: yöntem açıklaması','Log loss: method explanation'),'https://developers.google.com/machine-learning/crash-course/logistic-regression/loss-regularization')
    link(t('Lojistik regresyon ve düzenlileştirme: yöntem belgesi','Logistic regression and regularisation: method documentation'),'https://scikit-learn.org/stable/modules/generated/sklearn.linear_model.LogisticRegression.html')

    chapter(18,'Önceki makale ile bu hesaplayıcı aynı çalışma mı?','The earlier publication and today’s calculator')
    p('Adibi ve Yazıcı’nın 2023 tarihli “Artificial Intelligence and Machine Learning Applications in Precision Medicine and Genomic Diagnostics” başlıklı kitap bölümü, alandaki uygulamaları tanıtan bir derlemedir. Bugünkü hesaplayıcının bağımsız doğrulama raporu değildir. Bölümün 72. sayfasındaki BRCA örneği, Yazıcı ve arkadaşlarının 2020 çalışmasına atıf yapar. Algoritma ve performans ayrıntıları için aşağıdaki özgün makaleyi esas alıyoruz.',
      'The 2023 book chapter by Adibi and Yazıcı, “Artificial Intelligence and Machine Learning Applications in Precision Medicine and Genomic Diagnostics”, reviews applications in the field. It is not an independent validation report for today’s calculator. Its BRCA example on printed page 72 cites Yazıcı and colleagues’ 2020 study. For algorithm and performance details, we use the original paper linked below.')
    table(['Özellik','2020 yayını','Bugünkü hesaplayıcı'],['Aspect','2020 publication','Today’s calculator'],[
        (t('Veri grubu','Data group'),t('2.070 yüksek riskli meme kanseri hastası; başlangıçta 125 özellik','2,070 high-risk breast cancer patients; initially 125 features'),t('Özgün geliştirme grubu: 1.295 kişi','Original development group: 1,295 people')),
        (t('Hedef','Target'),t('BRCA1/2 negatifliğini belirleme','Identification of BRCA1/2 negativity'),t('Kayıtlı pozitif sonuç olasılığı ve ayrı test sırası kuralları','Probability of a recorded positive result and separate test-priority rules')),
        (t('Yöntem','Method'),t('KNN, karar ağacı ve SVM karşılaştırmaları; dokuz özellikli veri grubu öne çıkarılır','Comparisons involving KNN, decision trees and SVM; highlights a nine-feature dataset'),t('Sınıf dengeli L2 lojistik regresyon + kayıtlı kalibrasyon; ayrı puan kartı','Class-balanced L2 logistic regression + stored calibration; a separate points card')),
        (t('Bildirilen ölçüt','Reported measure'),t('%92,88 doğruluk (accuracy)','92.88% accuracy'),t('Kayıtlı iç çapraz doğrulama AUC: 0,776; yöntem sınırlılıkları 11. bölümde','Stored internal cross-validation AUC: 0.776; methodological limitations in chapter 11')),
        (t('Bağımsız doğrulama','Independent validation'),t('Bu yayının bulunması bugünkü modeli doğrulamaz','This publication does not validate today’s model'),t('Geniş arşivden henüz uygun, tarihli bağımsız grup sağlanmadı','The expanded archive has not yet supplied an eligible, dated independent set')),
    ])
    note('2.070, 1.295 ve arşivdeki 2.148 farklı kayıt kapsamlarını anlatır. Bu sayılar toplanamaz veya birbirinden çıkarılarak yeni/bağımsız hasta sayısı bulunamaz. Yayın ile bugünkü veriler arasındaki kişi ve aile örtüşmesi, yalnız bu sayılardan anlaşılamaz.',
         'The published 2,070, the development group of 1,295 and the archive’s 2,148 describe different record scopes. They cannot be added or subtracted to infer new or independent patients. Counts alone do not establish patient or family overlap between the publication and today’s data.')
    p('Doğruluk, belirli bir karar eşiğinde doğru sınıflananların oranıdır. AUC ise eşikler boyunca sıralamayı özetler. %92,88 doğruluk ile 0,776 AUC aynı ölçekte iki başarı oranı değildir; doğrudan büyük-küçük karşılaştırması yapılamaz. Veri grubu, hedef etiket, sınıf dağılımı, hasta/aile ayrımı ve değerlendirme düzeni de eşleşmelidir.',
      'Accuracy is the proportion classified correctly at a particular decision threshold. AUC summarises ranking across thresholds. A reported accuracy of 92.88% and an AUC of 0.776 are not two success rates on the same scale and cannot be directly ranked. Data group, outcome labels, class balance, patient/family separation and evaluation design also matter.')
    p('Aynı araştırma alanı, yazarlar veya arşiv, aynı eğitilmiş model demek değildir. İki dakikadan kısa hesaplama süresi; bir genetik testin yerini alma, güvenli test azaltma, maliyet tasarrufu veya tedavi yararının ölçüldüğü anlamına gelmez. Bizim sitemiz bu sonuçları kanıtlanmış bir klinik yarar olarak sunmaz.',
      'Shared research interests, authors or archives do not establish that two tools are the same fitted model. A calculation taking under two minutes does not establish replacement of genetic testing, safe test reduction, cost savings or measured treatment benefit. Our site does not present those outcomes as established clinical benefits.')
    link(t('2020 özgün makale: PubMed kaydı ve tam metin bağlantısı','2020 original paper: PubMed record and full-text link'),'https://pubmed.ncbi.nlm.nih.gov/33488844/')
    link(t('2020 özgün makale: DOI','2020 original paper: DOI'),'https://doi.org/10.1155/2020/8594090')
    link(t('2023 derleme bölümü: İstanbul Üniversitesi yayınevi kaynağı','2023 review chapter: Istanbul University publisher source'),'https://cdn.istanbul.edu.tr/file/JTA6CLJ8T5/EC25505B5D6143DC9EFBED00E3B2F6A5')
    p('Bu ek bölümler eğitim içindir. Gerçek hasta verileriyle yeni analiz veya algoritma karşılaştırması yapılmadı; klinik model yeniden eğitilmedi, hesaplayıcının hesabı değiştirilmedi.',
      'These additions are educational. No new patient analysis or algorithm comparison was performed; the clinical model was not retrained and the calculator’s arithmetic was not changed.')
    chapter(19,'Modelin sorusu ve klinik fayda','The model’s question and clinical benefit')
    note('Modelin tahmin yapabilmesi ile hastaya yarar sağladığının gösterilmesi ayrı şeylerdir. Bu hesaplayıcı, bağımsız doğrulaması henüz tamamlanmamış bir araştırma prototipidir.',
         'Making predictions and demonstrating a benefit to patients are separate achievements. This calculator is a research prototype whose independent validation has not yet been completed.')
    heading('Hangi soruya cevap arıyoruz?','What question are we asking?')
    p('Meme veya yumurtalık kanseri tanısı almış bir kişinin yaşı, ailedeki kanser öyküsü ve seçilmiş tümör özellikleri, BRCA1/BRCA2 testinin pozitif çıkmasına dair ipucu verebilir mi? Modelin araştırdığı soru budur. Kanser tanısı zaten vardır; model kanseri yeniden teşhis etmez. Öğrendiği ilişkiler, seçilmiş bir başvuru grubunun geçmiş kayıtlarından gelir; toplumdaki herkes için geçerli bir risk hesabı değildir.',
      'Can age, family cancer history and selected tumour features provide clues about a positive BRCA1/BRCA2 test result in someone already diagnosed with breast or ovarian cancer? That is the research question. Cancer has already been diagnosed; the model does not diagnose it again. Its learned relationships come from historical records in a selected referral group, rather than a general-population risk study.')
    p('Teknik olarak eğitim hedefi, özgün 1.295 kişideki kayıtlı sonuçtur: BRCA_status_v3_strict etiketi Positive ise 1, diğer etiketler için 0. Bu nedenle 1.128 sıfır etiketinin tamamını güncel, eksiksiz doğrulanmış klinik negatiflik olarak yorumlayamayız. Ekrandaki yüzde genetik raporun yerine geçmez.',
      'Training used the original 1,295 recorded outcomes. BRCA_status_v3_strict = Positive was coded 1; all other labels were coded 0. The 1,128 zeros are not necessarily complete, up-to-date, clinically verified negatives. The displayed percentage does not replace a genetic laboratory report.')
    table(['Soru','Bu model ne yapıyor?','Nasıl yorumlanmalı?'],['Question','What does this model do?','How should it be interpreted?'],[
        (t('BRCA sonucu','BRCA result'),t('Klinik bilgilerden kayıtlı pozitif sonuç olasılığını tahmin eder.','Estimates the probability of a recorded positive result from clinical information.'),t('Genetik testin kendisi değildir; hangi varyantın bulunduğunu göstermez.','It is not the genetic test and does not identify a specific variant.')),
        (t('Gelecekteki risk','Future risk'),t('Sağlıklı kişide kanser, ikinci kanser veya akrabanın riskini hesaplamaz.','Does not estimate cancer in healthy people, second cancers or a relative’s risk.'),t('Örneğin %20 sonucu, %20 kanser riski anlamına gelmez.','For example, a 20% output does not mean a 20% cancer risk.')),
        (t('Tedavi','Treatment'),t('PARP inhibitörü yanıtını, sağkalımı veya tümördeki somatik BRCA durumunu hesaplamaz.','Does not predict PARP inhibitor response, survival or somatic BRCA status in a tumour.'),t('Tedavi seçimi ve aile değerlendirmesi genetik sonuç ve klinik değerlendirme gerektirir.','Treatment selection and family assessment require genetic results and clinical evaluation.')),
        (t('Test sırası','Test priority'),t('Olasılık, ayrı puan kartı ve sıra kurallarıyla araştırma senaryoları gösterir.','Displays research scenarios using probability, a separate points card and priority rules.'),t('Bir önceliklendirme fikrini incelemek, klinik yararı kanıtlamak değildir.','Exploring a priority strategy does not establish clinical benefit.')),
    ])
    heading('Klinik fayda neden henüz gösterilmiş değil?','Why has clinical benefit not yet been demonstrated?')
    p('Genetik test sonucu tedavi seçimi ve aile takibi için değerli olabilir. Ancak bu, test sonucunu tahmin eden modelin bakım sürecini iyileştirdiğini kendiliğinden göstermez. Mevcut çalışmada model kullanılarak bekleme süresinin kısaldığı, tedavi kararının daha erken veya daha doğru verildiği, maliyetin azaldığı ya da hasta sonuçlarının iyileştiği ölçülmedi. Kayıtlı test paketi sayıları ve hedef yakalama oranları bu sonuçların yerine geçmez.',
      'A genetic test result can inform treatment and family care. That does not automatically establish that a model predicting that result improves care. The existing work did not measure shorter waiting times, earlier or better treatment decisions, reduced costs or improved patient outcomes from using the model. Stored package counts and target-detection rates do not substitute for those outcomes.')
    p('İlk hasta grubunun içindeki başarı ölçümleri de bağımsız doğrulama değildir. Veri hazırlama, ailelerin birbirinden ayrılması ve eksik kayıtlarla ilgili sınırlılıklar sürüyor. Somut klinik yarar iddiası için, ayrı hasta ve ailelerde güvenilirlik ile mevcut test yaklaşımına ek katkının ayrıca gösterilmesi gerekir. Bu rehber böyle bir yeni değerlendirme yapmaz; mevcut kanıtın sınırını anlatır.',
      'Performance within the original patient group is not independent validation. Limitations involving data preparation, family separation and missing records remain. A clinical-benefit claim would additionally require reliability in separate patients and families, and a demonstrated contribution beyond the existing testing approach. This guide performs no new evaluation; it explains the limits of the existing evidence.')
    note('Modelde düşük yüzde çıkması, kılavuza göre önerilen bir genetik testten vazgeçme gerekçesi olarak sunulamaz. Mevcut sonuçlar, güvenli test azaltmanın veya kanıtlanmış bir tedavi yararının gösterimi değildir.',
         'A low model probability must not be presented as a reason to withhold guideline-recommended genetic testing. The existing results do not establish safe test reduction or a proven treatment benefit.')
    link(t('NCI: BRCA değişiklikleri ve genetik testin klinik anlamı','NCI: BRCA changes and the clinical meaning of genetic testing'),'https://www.cancer.gov/about-cancer/causes-prevention/genetics/brca-fact-sheet')
    link(t('ASCO–SSO 2024: meme kanserinde kalıtsal genetik test kılavuzu','ASCO–SSO 2024: germline testing guideline for breast cancer'),'https://doi.org/10.1200/JCO.23.02225')
    chapter(20,'Gerçek modelimiz katsayıları nasıl öğrendi?','How did our actual model learn its coefficients?')
    note('Bu bölüm, mevcut eğitim kodunu ve kayıtlı modeli adım adım açıklar. Eğitim yeniden çalıştırılmadı. Gerçek eğitimin her yinelemesindeki katsayıların kaydı elimizde yok; aşağıdaki anlatım böyle bir tarihçenin yeniden oynatımı değildir.',
         'This chapter explains the existing training code and saved model step by step. Training was not rerun. We do not have a coefficient log for every iteration of actual training; this explanation is not a replay of that history.')
    heading('1 · Soruların yanında bildiğimiz cevaplar vardı','1 · The inputs came with known answers')
    p('Her satır bir kişiyi, sütunlar tanı yaşı, ailedeki kanserler ve belirli tümör özelliklerini temsil ediyordu. Bilgisayara kayıtlı BRCA sonucu da verildi. 1.295 kişiden 167’si Positive etiketiyle 1, diğer 1.128’i 0 olarak kodlandı. Sıfır etiketinin her kişide güncel ve eksiksiz klinik negatiflik kanıtı olmadığını unutmamalıyız. Biz hangi bilgilerin kullanılacağını ve hedefi seçtik; katsayıları tek tek biz belirlemedik.',
      'Each row represented a person; columns described diagnosis age, family cancers and selected tumour features. The recorded BRCA outcome was also supplied. Among 1,295 people, 167 labelled Positive were coded 1 and the other 1,128 were coded 0. A zero does not establish complete, current clinical negativity in every person. We selected the inputs and target; we did not assign the coefficients individually.')
    heading('2 · Kayıtlar sayılara çevrildi','2 · Records became numerical inputs')
    p('Yaş 38, erken meme kanserli birinci derece akraba sayısı 1, TNBC varlığı 1 gibi sayılar kullanıldı. Tanı ve bölge kategorileri ayrı 0/1 sütunlarına dönüştürüldü; toplam 26 girdi oluştu. Eksikler mevcut kurallarla dolduruldu; yaş ve Ki-67 için ayrıca eksiklik göstergeleri kullanıldı. Yaş, aile sayımları ve Ki-67 eğitimde ortak bir ölçeğe getirildi. Bu işlem, büyük sayılı bir ölçümün sırf birimi nedeniyle diğerlerini bastırmasını önlemeye yardımcı olur.',
      'Inputs included age 38, one first-degree relative with early breast cancer and TNBC present as 1. Diagnosis and region categories became separate 0/1 columns, producing 26 inputs. Missing values followed the existing filling rules, with missingness indicators for age and Ki-67. Age, family counts and Ki-67 were standardised for fitting. This helps prevent measurement units alone from giving larger numerical values undue influence.')
    heading('3 · Bir katsayı takımıyla herkese tahmin yapıldı','3 · A coefficient set produced a prediction for each person')
    p('Her girdi kendi katsayısıyla çarpıldı; başlangıç değeriyle birlikte toplandı. Bu toplam z, sigmoid denen dönüşümle 0 ile 1 arasında bir olasılığa çevrildi. Burada β₀ başlangıç değeri, βⱼ j numaralı girdinin katsayısı, xⱼ o girdinin değeri, p ise ham olasılıktır.',
      'Each input was multiplied by its coefficient and added to an intercept. The total z was converted into a probability between 0 and 1 using the sigmoid. Here β₀ is the intercept, βⱼ the coefficient for input j, xⱼ that input’s value and p the raw probability.')
    equation(r'z=\beta_0+\sum_{j=1}^{26}\beta_jx_j,\qquad p=\frac{1}{1+e^{-z}}')
    heading('4 · Tahminler kayıtlı sonuçlarla karşılaştırıldı','4 · Predictions were compared with recorded outcomes')
    p('Pozitif kayda düşük, sıfır etiketli kayda yüksek olasılık vermek hatayı artırdı. Kullanılan logaritmik kayıp, kendinden emin yanlış tahmini daha ağır cezalandırır. Pozitif kayıtlar az olduğu için sınıf ağırlıkları kullanıldı. Tam veriyle son eğitimde pozitif kaydın ağırlığı yaklaşık 3,88; diğer kaydınki 0,57 idi. Bunlar katsayı veya hasta olasılığı değil, eğitim hatasına verilen ağırlıklardır; eğitim alt gruplarında o grubun dağılımına göre hesaplanır.',
      'Low probabilities for positive records and high probabilities for zero-labelled records increased error. Logarithmic loss penalises confident wrong predictions more strongly. Class weights addressed the smaller positive group. For final fitting on all records, a positive record had weight about 3.88 and another record about 0.57. These are weights on training error, not coefficients or patient probabilities; training subsets calculate them from their own class counts.')
    heading('5 · Katsayılar, toplam hatayı azaltacak yönde birlikte değiştirildi','5 · Coefficients were adjusted together to reduce overall error')
    p('Eğitim yazılımı, her katsayıdaki değişimin toplam hatayı nasıl etkileyeceğini hesaplayarak daha iyi bir katsayı takımına ilerledi. Bir aile öyküsü katsayısını artırmak bazı tahminleri iyileştirip diğerlerini kötüleştirebilir; bu yüzden bütün bilgiler birlikte değerlendirilir. Yeterli yakınsamaya kadar yineleme yapılır; kodun üst sınırı 5.000’dir. Bu sayı, mutlaka 5.000 adım atıldığı anlamına gelmez. Gerçek modelin optimizasyonu, kurgu gösterimdeki basit güncelleme döngüsünün birebir aynısı olarak sunulmamalıdır.',
      'The optimiser assessed how changing coefficients would affect total error and moved towards a better coefficient set. Increasing a family-history coefficient can help some predictions and harm others, so inputs are considered jointly. Iteration continues until convergence criteria are met, subject to a maximum of 5,000 iterations in the code. That is not evidence that exactly 5,000 steps were taken. Actual optimisation must not be presented as identical to the simple update loop in the synthetic demonstration.')
    heading('6 · Ezberlemeyi sınırlayan frenin gücü seçildi','6 · The strength of a brake against overfitting was selected')
    p('L2 cezası, katsayıların gereksiz büyümesine bedel ekler. Bu frenin ayarı C’dir: küçük C daha güçlü fren demektir. 0,01; 0,03; 0,1; 0,3 ve 1 denendi. Beş dış parçalı değerlendirme beş kez tekrarlandı; her dış eğitim grubunda üç iç parçayla AUC üzerinden C seçildi. AUC, pozitif kayıtları daha yukarı sıralama başarısını özetler. En sık seçilen C, 0,3 oldu. Katsayıları öğrenmenin hedefi cezalı hatayı azaltmak; C’yi seçmenin ölçütü AUC idi.',
      'The L2 penalty adds a cost for unnecessarily large coefficients. C controls this brake: smaller C means stronger regularisation. Candidates were 0.01, 0.03, 0.1, 0.3 and 1. Five outer splits were repeated five times; three inner splits within each outer training set selected C by AUC. AUC summarises how well positive records rank higher. The most frequently selected C was 0.3. Fitting coefficients minimised penalised error; selecting C used AUC.')
    heading('7 · Son katsayılar bütün geliştirme grubuyla öğrenilip kaydedildi','7 · Final coefficients were fitted on the complete development group and saved')
    p('C = 0,3 ile 1.295 kişinin tamamına son model kuruldu. Ölçeklenmiş katsayılar, panelde doğrudan yıl ve kişi sayısı kullanılabilsin diye ham birimlere çevrildi. Kayıtlı yaş katsayısı yaklaşık −0,02974; 40 yaşından önce meme kanserli birinci derece akraba sayısının katsayısı +1,61777; TNBC göstergesininki +0,80950’dir. Bunlar yüzde puan değildir: önce z toplamına katkı yapar. Diğer girdilerle birlikte öğrenilmiş ilişkileri temsil eder; tek başına biyolojik neden-sonuç kanıtı değildir.',
      'With C = 0.3, the final model was fitted on all 1,295 people. Standardised coefficients were converted to raw units so the panel can use years and relative counts directly. Stored coefficients are approximately −0.02974 for age, +1.61777 for the number of first-degree relatives with breast cancer before 40, and +0.80950 for TNBC. These are not percentage points: they first contribute to z. They describe jointly learned associations, not proof of biological causation.')
    heading('8 · Yüzdeler için ayrı bir düzeltme öğrenildi','8 · A separate probability correction was learned')
    p('Kişilerin dış değerlendirme parçasında elde edilen ham olasılıkları tekrarlar boyunca ortalandı. Bu tahminlerin logit değerlerinden Platt kalibrasyonu adlı ayrı düzeltme öğrenildi. Panel, kayıtlı a ve b sayılarını son modelin z toplamına uygular. Aşağıda η düzeltilmiş toplamı, pcal son olasılığı gösterir. Bu düzeltme, bağımsız hastalarda doğrulamanın yerine geçmez.',
      'Raw probabilities obtained in each person’s outer evaluation split were averaged across repeats. A separate Platt calibration was fitted to the logits of those predictions. The panel applies the stored a and b to the final model’s z. Below, η is the corrected total and pcal the final probability. This correction does not replace validation in independent patients.')
    equation(r'\eta=-1.82409575+0.93922755z,\qquad p_{\mathrm{cal}}=\frac{1}{1+e^{-\eta}}')
    heading('Gerçek eğitim ve kurgu gösterim: aynı şey değiller','Actual training and the synthetic demonstration are different')
    table(['Özellik','Gerçek BRCA modeli','Kurgu öğrenme gösterimi'],['Feature','Actual BRCA model','Synthetic learning demonstration'],[
        (t('Veri','Data'),t('1.295 kişinin geçmiş kayıtları; 26 girdi','Historical records of 1,295 people; 26 inputs'),t('Sekiz kurgu örnek; A ve B tıbbi ölçüm değil','Eight invented examples; A and B are not medical measurements')),
        (t('Öğrenme','Learning'),t('Sınıf ağırlıkları, L2 cezası, C seçimi ve ayrı kalibrasyon','Class weights, L2 penalty, C selection and separate calibration'),t('Öğretici basit güncelleme; sınıf ağırlığı ve kalibrasyon yok','Simple teaching updates; no class weights or calibration')),
        (t('Görülen adımlar','Visible steps'),t('Son katsayılar ve kod var; her yinelemenin katsayı kaydı yok','Final coefficients and code exist; no per-iteration coefficient log'),t('Kurgu veriye göre tarayıcıda hesaplanan öğretici adımlar','Teaching steps calculated in the browser from synthetic data')),
        (t('Girdi değişikliği','Changing inputs'),t('Panelde kayıtlı katsayılar sabit; yalnız kişinin hesabı değişir','Stored panel coefficients stay fixed; only the person’s calculation changes'),t('Kurgu veriyi değiştirince örnek eğitim yeniden başlar','Editing synthetic data restarts the illustrative training')),
    ])
    note('Kurgu gösterim, gerçek modelin geçmişte nasıl eğitildiğine ait bir video veya klinik başarı kanıtı değildir. Mevcut eğitimde eksik doldurma ve ölçekleme dış ayrımdan önce yapılmış; ayırma da aile gruplu değildir. Bu nedenle aile bağımsızlığı ve tamamen ayrım içinde öğrenilen veri hazırlama güvence altında değildir. Yeni hasta ve ailelerde bağımsız doğrulama hâlâ gerekir. Puan kartı da ana katsayıları yuvarlayarak değil, ayrı bir modelle oluşturulmuştur.',
         'The synthetic demonstration is neither a recording of actual historical training nor evidence of clinical performance. In the recovered training process, imputation and scaling preceded the outer split, and splitting was not grouped by family. Family independence and fully split-contained preprocessing are therefore not guaranteed. Independent validation in new patients and families remains necessary. The points card was fitted separately, rather than obtained by rounding the main coefficients.')
    return blocks
